comments.suggestion_code:
const fence = /^\s*(`{3,}|~{3,})/.exec(line);
if (fence) {
  const ch = fence[1]?.[0] ?? "";
  if (!inFence) {
    inFence = true;
    fenceChar = ch;
  } else if (ch === fenceChar) {
    // Closing fence: must be ONLY the fence char (no info string) per CommonMark.
    const trimmed = line.trim();
    const fenceLen = fence[1].length;
    if (trimmed.length === fenceLen) {
      inFence = false;
      fenceChar = "";
    }
  }
}

